import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input through unchanged to the executor', async () => {
    const registry = new ToolRegistry();
    let receivedInput: Record<string, unknown> | null = null;

    registry.register(
      {
        name: 'test_tool',
        description: 'A tool for testing',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, extra: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        receivedInput = input;
        return 'success';
      }
    );

    const inputWithExtraProperty = {location: 'Paris', extra: 'ignored'};
    const result = await registry.execute('test_tool', inputWithExtraProperty);

    expect({
      resultIsSuccess: result.result === 'success',
      inputUnchanged: receivedInput === inputWithExtraProperty,
      extraPropertyPreserved: receivedInput && (receivedInput as Record<string, unknown>).extra === 'ignored',
    }).toEqual({
      resultIsSuccess: true,
      inputUnchanged: true,
      extraPropertyPreserved: true,
    });
  });

  it('includes field name in type error message', async () => {
    const registry = new ToolRegistry();
    let executorCalled = false;

    registry.register(
      {
        name: 'type_check_tool',
        description: 'A tool for type checking',
        inputSchema: {
          type: 'object',
          properties: {userId: {type: 'string'}},
          required: ['userId'],
        },
      },
      async () => {
        executorCalled = true;
        return 'success';
      }
    );

    const response = await registry.execute('type_check_tool', {userId: 12345});

    expect({
      executorWasNotCalled: !executorCalled,
      includesFieldName: response.result.includes('userId'),
      includesType: response.result.includes('string'),
      noValueLeak: !response.result.includes('12345'),
    }).toEqual({
      executorWasNotCalled: true,
      includesFieldName: true,
      includesType: true,
      noValueLeak: true,
    });
  });
});

